import { readFileSync } from "node:fs";
import { resolve } from "node:path";
import { pathToFileURL } from "node:url";
const root = process.cwd();
const helper = await import(pathToFileURL(resolve(root, ".agro/scripts/__tests__/helpers/sandbox-routing.ts")));
helper.gradeObservedFile(root);
const record = JSON.parse(readFileSync(resolve(root, helper.decisionsFile), "utf8"));
const cases = helper.loadCases(root);
console.log(JSON.stringify({
  method: "Executed the real gradeObservedFile function, then exposed its unchanged frozen case/observed-response comparisons.",
  graderReturnedNormally: true,
  recordKind: record.provenance.kind,
  provenance: helper.sourceProvenance(root),
  ownerRule: "All required owners must be present; additional allowed owners are unpenalized.",
  commandRule: "Suggested command strings and notes are preserved, not executed or wording-graded.",
  cases: cases.map(scenario => {
    const observed = record.decisions.find(value => value.caseId === scenario.id);
    return {
      caseId: scenario.id,
      prompt: scenario.prompt,
      expectedRoute: scenario.oracle.route,
      observedRoute: observed.response.route,
      requiredOwners: scenario.oracle.owners,
      observedOwners: observed.response.owners,
      routeMatches: observed.response.route === scenario.oracle.route,
      requiredOwnersPresent: scenario.oracle.owners.every(owner => observed.response.owners.includes(owner)),
    };
  }),
  limits: ["No new model contexts or substituted responses.", "No provider, workload or suggested-command execution.", "This is a bounded eight-case decision sample, not general task reliability."]
}, null, 2));
